        const endTok = this.next();
        if (endTok.t !== 'ident' || !REF_RE.test(endTok.v))
          throw new Error(`Range end must be a cell ref, got "${endTok.t === 'ident' ? endTok.v : endTok.t}"`);
        if (!REF_RE.test(tok.v)) throw new Error(`Range start must be a cell ref, got "${tok.v}"`);
        return { kind: 'range', start: tok.v, end: endTok.v };
      }
      if (nxt && nxt.t === 'lp' && FUNCTIONS.has(tok.v)) {
        this.next(); // (
        const args: Ast[] = [];
        if (this.peek() && this.peek()!.t !== 'rp') {
          args.push(this.parseArg());
          while (this.peek() && this.peek()!.t === 'comma') {
            this.next();
            args.push(this.parseArg());
          }
        }
        const close = this.next();
        if (close.t !== 'rp') throw new Error('Expected ")" after function arguments');
        return { kind: 'call', fn: tok.v as 'SUM' | 'AVG', args };
      }
      if (REF_RE.test(tok.v)) return { kind: 'ref', ref: tok.v };
      throw new Error(`Unknown identifier "${tok.v}"`);
    }

    if (tok.t === 'lp') {
      const inner = this.parseExpr();
      const close = this.next();
      if (close.t !== 'rp') throw new Error('Expected ")"');
      return inner;
    }

    throw new Error(`Unexpected token ${JSON.stringify(tok)}`);
  }

  private parseArg(): Ast {
    // An argument may be a plain expression or an explicit range A1:B2.
    const tok = this.peek();
    if (tok && tok.t === 'ident' && REF_RE.test(tok.v) && this.tokens[this.pos + 1]?.t === 'colon') {
      const start = this.next().v as string;
      this.next(); // colon
      const endTok = this.next();
      if (endTok.t !== 'ident' || !REF_RE.test(endTok.v)) throw new Error('Bad range end');
      return { kind: 'range', start, end: endTok.v };
    }
    return this.parseExpr();
  }
}

export function parseFormula(src: string): Ast {
  return new Parser(tokenize(src)).parse();
}

// ---------------------------------------------------------------------------
// Range helpers
// ---------------------------------------------------------------------------

function colToIndex(letters: string): number {
  let n = 0;
  for (const ch of letters) n = n * 26 + (ch.charCodeAt(0) - 64);
  return n - 1; // 0-based
}

function indexToCol(n: number): string {
  n += 1;
  let s = '';
  while (n > 0) {
    const rem = (n - 1) % 26;
    s = String.fromCharCode(65 + rem) + s;
    n = Math.floor((n - 1) / 26);
  }
  return s;
}

function splitRef(ref: string): { col: number; row: number } {
  const m = /^([A-Z]+)([0-9]+)$/.exec(ref);
  if (!m) throw new Error(`Invalid cell ref: ${ref}`);
  return { col: colToIndex(m[1]), row: parseInt(m[2], 10) - 1 };
}

export function* expandRange(start: string, end: string): Generator<string> {
  const a = splitRef(start);
  const b = splitRef(end);
  const c0 = Math.min(a.col, b.col), c1 = Math.max(a.col, b.col);
  const r0 = Math.min(a.row, b.row), r1 = Math.max(a.row, b.row);
  for (let r = r0; r <= r1; r++) for (let c = c0; c <= c1; c++) yield `${indexToCol(c)}${r + 1}`;
}

function collectDeps(ast: Ast, out: Set<string>): void {
  switch (ast.kind) {
    case 'ref':
      out.add(ast.ref);
      break;
    case 'range':
      for (const ref of expandRange(ast.start, ast.end)) out.add(ref);
      break;
    case 'neg':
      collectDeps(ast.arg, out);
      break;
    case 'bin':
      collectDeps(ast.left, out);
      collectDeps(ast.right, out);
      break;
    case 'call':
      for (const a of ast.args) collectDeps(a, out);
      break;
  }
}

// ---------------------------------------------------------------------------
// Engine
// ---------------------------------------------------------------------------

interface Cell {
  ref: string;
  raw: number | string | null;
  formula: Ast | null; // set iff raw is a "=..." formula
  value: CellValue;
  version: number; // engine version at which `value` was computed
  deps: Set<string>; // cells this cell references
}

interface EvalCtx {
  visiting: Map<string, number>; // ref -> depth in current DFS stack
  stack: string[];
  cycle: Set<string>; // cells proven to be part of a reference cycle
  done: Map<string, CellValue>;
  dirty: Set<string>; // cells that must be recomputed this round (empty => read-only)
}

export function createSheet() {
  const cells = new Map<string, Cell>();
  const dependents = new Map<string, Set<string>>(); // precedent -> who depends on it
  let version = 0;
  let recomputeCount = 0;

  function normalizeRef(rawRef: string): string {
    const ref = rawRef.trim().toUpperCase();
    if (!REF_RE.test(ref)) throw new Error(`Invalid cell ref: "${rawRef}"`);
    return ref;
  }

  function addEdge(from: string, to: string): void {
    let s = dependents.get(from);
    if (!s) dependents.set(from, (s = new Set()));
    s.add(to);
  }

  function removeEdge(from: string, to: string): void {
    const s = dependents.get(from);
    if (s) {
      s.delete(to);
      if (s.size === 0) dependents.delete(from);
    }
  }

  /** All cells transitively downstream of `ref`, including `ref` itself. */
  function collectDirty(ref: string): Set<string> {
    const dirty = new Set<string>();
    const queue = [ref];
    while (queue.length > 0) {
      const cur = queue.shift()!;
      if (dirty.has(cur)) continue;
      dirty.add(cur);
      const deps = dependents.get(cur);
      if (deps) for (const d of deps) if (!dirty.has(d)) queue.push(d);
    }
    return dirty;
  }

  function evalAst(ctx: EvalCtx, ast: Ast): CellValue {
    switch (ast.kind) {
      case 'num':
        return ast.value;
      case 'ref':
        return ensureValue(ctx, ast.ref);
      case 'neg': {
        const v = evalAst(ctx, ast.arg);
        if (isError(v)) return v;
        return -(v as number);
      }
      case 'bin': {
        const l = evalAst(ctx, ast.left);
        if (isError(l)) return l;
        const r = evalAst(ctx, ast.right);
        if (isError(r)) return r;
        const a = l as number, b = r as number;
        switch (ast.op) {
          case '+': return a + b;
          case '-': return a - b;
          case '*': return a * b;
          case '/': return b === 0 ? DIV0 : a / b;
        }
        break;
      }
      case 'call': {
        const nums: number[] = [];
        for (const arg of ast.args) {
          if (arg.kind === 'range') {
            for (const ref of expandRange(arg.start, arg.end)) {
              const v = ensureValue(ctx, ref);
              if (isError(v)) return v; // errors propagate through aggregates
              nums.push(v as number);
            }
          } else {
            const v = evalAst(ctx, arg);
            if (isError(v)) return v;
            nums.push(v as number);
          }
        }
        if (nums.length === 0) return DIV0;
        const sum = nums.reduce((s, x) => s + x, 0);
        return ast.fn === 'SUM' ? sum : sum / nums.length;
      }
    }
    throw new Error('Unreachable AST node');
  }

  /**
   * Lazily evaluate a single cell with memoization and on-the-fly cycle
   * detection. Only cells in ctx.dirty actually recompute (and increment the
   * counter); everything else is served from cache or promoted to the current
   * engine version without work.
   */
  function ensureValue(ctx: EvalCtx, rawRef: string): CellValue {
    const ref = normalizeRef(rawRef);

    // Back-edge found while DFS is running => every cell from the first
    // occurrence down to the top of the stack is part of a cycle.
    const visitDepth = ctx.visiting.get(ref);
    if (visitDepth !== undefined) {
      for (let i = visitDepth; i < ctx.stack.length; i++) ctx.cycle.add(ctx.stack[i]);
      return CYCLE;
    }

    const cached = ctx.done.get(ref);
    if (cached !== undefined) return cached;

    const cell = cells.get(ref);
    if (!cell || cell.raw === null) return 0; // empty cells read as 0

    if (!ctx.dirty.has(ref)) {
      // Not affected by any edit: its cached value is still correct, just
      // promote it to the current engine version.
      cell.version = version;
      ctx.done.set(ref, cell.value);
      return cell.value;
    }

    ctx.visiting.set(ref, ctx.stack.length);
    ctx.stack.push(ref);
    recomputeCount++; // one unit of real recomputation work per dirty cell

    let value: CellValue;
    try {
      if (cell.formula) value = evalAst(ctx, cell.formula);
      else if (typeof cell.raw === 'number') value = cell.raw;
      else value = cell.raw; // plain text literal

      if (ctx.cycle.has(ref)) value = CYCLE; // membership in a cycle wins
    } finally {
      ctx.stack.pop();
      ctx.visiting.delete(ref);
    }

    cell.value = value;
    cell.version = version;
    ctx.done.set(ref, value);
    return value;
  }

  function set(rawRef: string, raw: number | string | null): void {
    const ref = normalizeRef(rawRef);

    let cell = cells.get(ref);
    if (!cell) {
      cell = { ref, raw: null, formula: null, value: 0, version: -1, deps: new Set() };
      cells.set(ref, cell);
    }

    // Rewire dependency edges for the new content.
    for (const d of cell.deps) removeEdge(d, ref);
    cell.deps.clear();

    let formula: Ast | null = null;
    if (typeof raw === 'string' && raw.startsWith('=')) {
      formula = parseFormula(raw.slice(1));
      collectDeps(formula, cell.deps);
      for (const d of cell.deps) addEdge(d, ref);
    }
    cell.formula = formula;
    cell.raw = raw;

    version++;

    // Recompute exactly the edited cell plus its transitive dependents —
    // nothing else in the sheet does work this round.
    const dirty = collectDirty(ref);
    const ctx: EvalCtx = {
      visiting: new Map(),
      stack: [],
      cycle: new Set(),
      done: new Map(),
      dirty,
    };
    for (const r of dirty) ensureValue(ctx, r);
  }

  function get(rawRef: string): CellValue {
    const ref = normalizeRef(rawRef);
    const cell = cells.get(ref);
    if (!cell || cell.raw === null) return 0;
    // Read-only evaluation: never counts toward the recompute counter.
    const ctx: EvalCtx = {
      visiting: new Map(),
      stack: [],
      cycle: new Set(),
      done: new Map(),
      dirty: new Set(),
    };
    return ensureValue(ctx, ref);
  }

  function has(rawRef: string): boolean {
    const ref = normalizeRef(rawRef);
    const cell = cells.get(ref);
    return !!cell && cell.raw !== null;
  }

  return {
    set,
    get,
    has,
    /** Total number of individual cell recomputations performed so far. */
    get recomputeCount(): number {
      return recomputeCount;
    },
  };
}

